using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Pure and applied mathematics including statistics and data science." },
        new() { Id = 3, Name = "English", Code = "ENG", Description = "Literature, writing, and language studies." },
        new() { Id = 4, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Exploration of past events, civilizations, and cultural developments." },
    ];

    private static readonly List<Course> Courses =
    [
        new() { Id = 1, Title = "Introduction to Programming", Code = "CS 101", Description = "Fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen specializes in computer science education and has published extensively on introductory programming pedagogy. She received her PhD from Stanford University.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 2, Title = "Data Structures and Algorithms", Code = "CS 201", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques. Includes analysis of time and space complexity.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Park", InstructorBio = "Dr. Park's research focuses on algorithm optimization and computational complexity. He previously worked at Google Research.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
        new() { Id = 3, Title = "Database Systems", Code = "CS 340", Description = "Relational database design, SQL, normalization, transaction processing, and an introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez has 15 years of industry experience in database architecture at Oracle and Amazon before joining academia.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
        new() { Id = 4, Title = "Calculus I", Code = "MATH 151", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning mathematics educator known for making calculus accessible to all students.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
        new() { Id = 5, Title = "Linear Algebra", Code = "MATH 220", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Anika Patel", InstructorBio = "Dr. Patel researches applied linear algebra and its connections to machine learning and data science.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
        new() { Id = 6, Title = "Statistics and Probability", Code = "MATH 300", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning mathematics educator known for making calculus accessible to all students.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
        new() { Id = 7, Title = "Creative Writing", Code = "ENG 210", Description = "Workshop-based course in fiction, poetry, and creative nonfiction. Students develop a portfolio of original work.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Prof. Elizabeth Hart", InstructorBio = "Prof. Hart is a published novelist and poet whose work has appeared in The New Yorker and The Atlantic.", DepartmentId = 3, DepartmentName = "English", IsFeatured = true },
        new() { Id = 8, Title = "American Literature", Code = "ENG 320", Description = "Survey of American literature from the colonial period to the present, including diverse voices and perspectives.", Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is a scholar of 20th-century American fiction with a focus on multicultural narratives.", DepartmentId = 3, DepartmentName = "English", IsFeatured = false },
        new() { Id = 9, Title = "Classical Mechanics", Code = "PHYS 201", Description = "Newtonian mechanics, Lagrangian and Hamiltonian formulations, oscillations, and central force problems.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Helen Zhao", InstructorBio = "Dr. Zhao's research spans theoretical physics and astrophysics. She is a Fellow of the American Physical Society.", DepartmentId = 4, DepartmentName = "Physics", IsFeatured = false },
        new() { Id = 10, Title = "Quantum Physics", Code = "PHYS 310", Description = "Introduction to quantum mechanics: wave-particle duality, Schrödinger equation, angular momentum, and atomic structure.", Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Helen Zhao", InstructorBio = "Dr. Zhao's research spans theoretical physics and astrophysics. She is a Fellow of the American Physical Society.", DepartmentId = 4, DepartmentName = "Physics", IsFeatured = true },
        new() { Id = 11, Title = "World History to 1500", Code = "HIST 101", Description = "Survey of global civilizations from prehistory through the late medieval period.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. David Okafor", InstructorBio = "Dr. Okafor is a specialist in comparative world history with fieldwork experience across three continents.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
        new() { Id = 12, Title = "Modern European History", Code = "HIST 250", Description = "Europe from the French Revolution to the present: political upheaval, industrialization, world wars, and the EU.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. Claire Dubois", InstructorBio = "Dr. Dubois specializes in modern French and German history and is the author of two acclaimed monographs.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
    ];

    public List<Department> GetDepartments() => Departments;

    public Department? GetDepartment(int id) => Departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => Courses;

    public List<Course> GetFeaturedCourses() => Courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => Courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = Courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

